// ─────────────────────────────────────────────
// NODE 2: Validate & normalise incoming payload
// ─────────────────────────────────────────────
const body = $input.first().json.body || $input.first().json;

function makeUUID() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
    const r = Math.random() * 16 | 0;
    return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
  });
}

const required = ['tenant_id', 'customer_phone', 'platform', 'message_type'];
const missing = required.filter(f => !body[f]);
if (missing.length > 0) {
  throw new Error('Missing required fields: ' + missing.join(', '));
}

if (body.message_type === 'text' && !body.message) {
  throw new Error('Message content is empty');
}

return [{
  json: {
    tenant_id:           body.tenant_id,
    customer_phone:      String(body.customer_phone),
    customer_name:       body.customer_name || 'Customer',
    platform:            body.platform || 'whatsapp',
    message_type:        body.message_type || 'text',
    message:             body.message || '',
    external_message_id: body.external_message_id || makeUUID(),
    conversation_id:     body.conversation_id || null,
    phone_number_id:     body.phone_number_id || '',
    timestamp:           body.timestamp || new Date().toISOString(),
    processed_at:        new Date().toISOString()
  }
}];

// ─────────────────────────────────────────────
// NODE 3: Detect language from message content
// ─────────────────────────────────────────────
const body = $('Validate Payload').first().json;
const message = body.message || '';

let detected_language = 'en';
const arabicChars = (message.match(/[\u0600-\u06FF]/g) || []).length;
const urduChars   = (message.match(/[\u067E\u0686\u0698\u06AF\u06BA\u06C1\u06BE\u06CC]/g) || []).length;

if (arabicChars > 0) {
  detected_language = (urduChars / arabicChars > 0.15) ? 'ur' : 'ar';
}

return [{ json: { ...body, detected_language, normalized_message: message.trim() } }];

// ─────────────────────────────────────────────
// NODE 5: Merge tenant with request + status check
// ─────────────────────────────────────────────
const requestData  = $('Detect Language').first().json;
const tenantItems  = $input.all();

if (!tenantItems || tenantItems.length === 0 || !tenantItems[0].json.id) {
  throw new Error('Tenant not found for id: ' + requestData.tenant_id);
}

const tenant = tenantItems[0].json;

if (tenant.status && tenant.status !== 'active') {
  throw new Error('TENANT_SUSPENDED');
}

return [{
  json: {
    // Request fields
    tenant_id:           requestData.tenant_id,
    customer_phone:      requestData.customer_phone,
    customer_name:       requestData.customer_name,
    platform:            requestData.platform,
    message_type:        requestData.message_type,
    message:             requestData.message,
    external_message_id: requestData.external_message_id,
    conversation_id:     requestData.conversation_id,
    phone_number_id:     requestData.phone_number_id,
    processed_at:        requestData.processed_at,
    detected_language:   requestData.detected_language,
    normalized_message:  requestData.normalized_message,

    // Tenant fields
    tenant:              tenant,
    business_name:       tenant.business_name || tenant.name,
    niche:               tenant.niche || 'general',
    wa_phone_number_id:  tenant.wa_phone_number_id,
    wa_access_token:     tenant.wa_access_token,

    // AI config — from migrated columns (fallback to safe defaults)
    ai_model:            tenant.ai_model       || 'gpt-4o-mini',
    ai_temperature:      parseFloat(tenant.ai_temperature) || 0.7,
    ai_max_tokens:       parseInt(tenant.ai_max_tokens)    || 500,
    ai_language:         tenant.ai_language    || requestData.detected_language || 'ar'
  }
}];

// ─────────────────────────────────────────────
// NODE 8: Prepare OpenAI embedding request body
// ─────────────────────────────────────────────
const ctx = $('Merge Tenant').first().json;

const embedBody = JSON.stringify({
  model: 'text-embedding-3-small',
  input: ctx.normalized_message
});

return [{ json: { ...ctx, embed_request_body: embedBody } }];

// ─────────────────────────────────────────────
// NODE 10: Prepare vector search request body
// ─────────────────────────────────────────────
const ctx       = $('Merge Tenant').first().json;
const embedResp = $input.first().json;

// Extract embedding vector — gracefully handle embedding failure
const embedding = embedResp?.data?.[0]?.embedding || [];

const searchBody = JSON.stringify({
  query_embedding: embedding,
  p_tenant_id:     ctx.tenant_id,
  match_threshold: 0.10,
  match_count:     5
});

return [{ json: { ...ctx, embedding, search_request_body: searchBody } }];

// ─────────────────────────────────────────────
// NODE 12: Assemble full context for AI
// ─────────────────────────────────────────────
const ctx       = $('Merge Tenant').first().json;
const agentItem = $('Load Agent').first().json;
const convItem  = $('Find Conversation').first().json;

// Extract knowledge base docs
const kbDocs = $('Search Knowledge Base').all()
  .map(item => item.json)
  .filter(doc => doc && doc.title && doc.content && !doc.error);

// Extract products
let productDocs = [];
try {
  productDocs = $('Search Products').all()
    .map(item => item.json)
    .filter(doc => doc && doc.name && !doc.error);
} catch(e) {}

// Agent prompt — from agents table
const agent      = agentItem?.id ? agentItem : null;
const agentPrompt = agent?.prompt ||
  `You are a helpful AI assistant for ${ctx.business_name}. Answer customer questions professionally.`;

// Format knowledge base entries
const kbEntries = kbDocs.length > 0
  ? kbDocs.map((kb, i) => `[${i + 1}] ${kb.title}:\n${kb.content}`).join('\n\n')
  : '';

// Format product entries (Phase 3 Commerce V2)
const productEntries = productDocs.length > 0
  ? productDocs.map(p => {
      let desc = p.description ? p.description.substring(0, 150) + '...' : '';
      return `- ${p.name} | Price: ${p.price} ${p.currency}\n  Category: ${p.category}\n  Desc: ${desc}\n  URL: ${p.product_url || ''}\n  Image: ${p.image_url || ''}`;
    }).join('\n\n')
  : '';

let finalContext = '';
if (kbEntries) finalContext += `=== GENERAL POLICIES & FAQS ===\n${kbEntries}\n\n`;
if (productEntries) finalContext += `=== LIVE PRODUCT CATALOG ===\n${productEntries}\n\n`;

// Existing conversation
const existingConv      = convItem?.id ? convItem : null;
const conversation_id   = ctx.conversation_id || existingConv?.id || null;
const is_new_conversation = !existingConv;

return [{
  json: {
    ...ctx,
    agent_prompt:       agentPrompt,
    kb_entries:         finalContext,
    kb_count:           kbDocs.length,
    product_count:      productDocs.length,
    conversation_id:    conversation_id,
    is_new_conversation: is_new_conversation
  }
}];

// ─────────────────────────────────────────────
// NODE 14: Build complete AI prompt
// ─────────────────────────────────────────────
const ctx          = $('Assemble Context').first().json;
const historyItems = $input.all();

const history = historyItems
  .map(item => item.json)
  .filter(m => m.id && m.content)
  .sort((a, b) => new Date(a.created_at) - new Date(b.created_at));

const language = ctx.detected_language || 'ar';

const nicheInstructions = {
  restaurant:    'You help customers with menu items, prices, opening hours, delivery, and reservations.',
  dental:        'You help patients with appointments, treatments, pricing, and clinic hours. Always recommend professional consultation.',
  real_estate:   'You help clients find properties, understand pricing, and arrange viewings.',
  salon:         'You help with bookings, services, available slots, and pricing.',
  ecommerce:     'You help with products, availability, orders, delivery, and returns.',
  food_delivery: 'You help with order tracking, menu items, delivery times, and issues.',
  medical:       'You help with appointments and general clinic information. Always recommend professional medical consultation.',
  general:       'You help customers with their inquiries professionally and helpfully.'
};

const languageInstructions = {
  ar: 'يجب أن تجيب باللغة العربية الفصحى أو بنفس لهجة العميل. اجعل ردودك طبيعية ودافئة.',
  ur: 'آپ کو اردو میں جواب دینا ہے۔ قدرتی اور دوستانہ زبان استعمال کریں۔',
  en: 'Reply in clear, warm, conversational English.'
};

// NEW IN PHASE 3: Tell AI how to format product cards if we want to add UI later
const productCardInstruction = "\n\n--- PRODUCT MEDIA MESSAGES ---\nIf you are recommending a product from the LIVE PRODUCT CATALOG and it has an Image URL, you should format your response nicely so the user sees the product clearly.";

const kbSection = ctx.kb_entries
  ? `KNOWLEDGE BASE (${ctx.kb_count} relevant results):\n${ctx.kb_entries}`
  : 'KNOWLEDGE BASE: No specific content found. Answer only from what you know about this business from the system prompt above.';

// ── NEW: pull the existing order row, if any ──
let existingOrderRows = [];
try {
  existingOrderRows = $('Load Existing Orders').first().json;
  if (!Array.isArray(existingOrderRows)) existingOrderRows = [existingOrderRows];
} catch (e) {
  existingOrderRows = [];
}
const existingOrder = (existingOrderRows && existingOrderRows[0]) || null;

let orderStateBlock = '';
if (['ecommerce', 'restaurant', 'food_delivery'].includes(ctx.niche) ) {
  if (existingOrder) {
    const items = Array.isArray(existingOrder.items) ? existingOrder.items : [];
    const itemsStr = items.length
      ? items.map(i => `${i.qty || 1}x ${i.name || 'item'}${i.price ? ` @ USD ${i.price}` : ''}`).join(', ')
      : '(none yet)';

    orderStateBlock = [
      '--- CURRENT ORDER STATE (authoritative — trust this over anything implied by chat history) ---',
      `Product(s): ${itemsStr}`,
      `Order total: ${existingOrder.order_amount ? 'USD ' + existingOrder.order_amount : '(not yet calculated)'}`,
      `Delivery address: ${existingOrder.delivery_address || '(not yet provided)'}`,
      `Email: ${existingOrder.customer_email || '(not yet provided)'}`,
      `Payment method: ${existingOrder.payment_method || '(not yet provided)'}`,
      `Status: ${existingOrder.status || 'pending_address'}`,
      '',
      'Instructions for using this state:',
      '- Only ask the customer for fields above that are still "(not yet provided)".',
      '- NEVER ask again for a field that already has a value here, even if you cannot see it stated in the recent chat history.',
      '- If Status is "confirmed", do not re-ask anything — just acknowledge the order is already confirmed and help with anything new.',
      '- If all fields are filled and Status is not yet "confirmed", ask the customer to confirm the order.',
      '- If the customer names a clearly different product than the one listed above, treat it as a new order and ignore the old product/quantity (but you may reuse a previously given delivery address or payment method if the customer does not provide a new one).',
    ].join('\n');
  } else {
    orderStateBlock = '--- CURRENT ORDER STATE ---\nNo order in progress yet for this conversation.';
  }
}

const systemPrompt = [
  `You are the AI assistant for ${ctx.business_name}.`,
  `Business type: ${ctx.niche || 'general'}`,
  '',
  ctx.agent_prompt,
  '',
  nicheInstructions[ctx.niche] || nicheInstructions.general,
  languageInstructions[language] || languageInstructions.en,
  '',
  '--- RULES ---',
  '1. Answer ONLY using the knowledge base content provided below.',
  '2. If the answer is not in the knowledge base, say you will connect the customer with a team member.',
  '3. NEVER invent prices, hours, availability, or contact details.',
  '4. Keep responses under 3 short paragraphs — be concise.',
  '5. Be warm, human, and conversational. Never sound robotic.',
  `6. Channel: ${ctx.platform}`,
  '',
  orderStateBlock,
  '',
  kbSection,
  '',
  '--- MANDATORY ORDER SUMMARY ---',
  'If you are actively handling an order, you MUST summarize the details at the end of your reply (especially when asking for an email, address, payment method, or confirming).',
  'Always include the Unit Price if known. Use this exact format:',
  '*Product(s)*: [Qty]x [Item Name] @ USD [Unit Price]',
  '*Total Amount*: USD [Total Amount]',
  '*Delivery Address*: [Address or Pending]',
  '*Email*: [Email Address or Pending]',
  '*Payment Method*: [Method or Pending]',
  '',
  '--- MANDATORY INTENT TAG ---',
  'At the VERY END of your message, on a new line, you MUST append exactly ONE of these tags:',
  'Intent: general_inquiry (for questions)',
  'Intent: order_placed (wants to buy, needs details)',
  'Intent: address_provided (user gave address)',
  'Intent: order_confirmed (user confirmed final order)',
  'Intent: checkout_intent (asking how to pay)',
  'Intent: human_handoff (user asked for human)',
  'Example: [Your reply...] \n\nIntent: order_placed'
].join('\n');

const messages = [{ role: 'system', content: systemPrompt }];

for (const msg of history) {
  if (msg.sender_type === 'customer') {
    messages.push({ role: 'user', content: msg.content });
  } else if (msg.sender_type === 'bot') {
    messages.push({ role: 'assistant', content: msg.content });
  }
}

messages.push({ role: 'user', content: ctx.normalized_message });

return [{
  json: {
    ...ctx,
    prompt_messages: messages,
    system_prompt:   systemPrompt,
    existing_order:  existingOrder
  }
}];

// ─────────────────────────────────────────────
// NODE 15: Prepare GPT request body
// Uses ai_model, ai_temperature, ai_max_tokens from migrated tenant columns
// ─────────────────────────────────────────────
const ctx = $input.first().json;

// These values come from tenants.ai_model / ai_temperature / ai_max_tokens
// set in Merge Tenant node — falls back to safe defaults
const model       = ctx.ai_model       || 'gpt-4o-mini';
const temperature = parseFloat(ctx.ai_temperature) || 0.7;
const max_tokens  = parseInt(ctx.ai_max_tokens)    || 500;

const gptBody = JSON.stringify({
  model:       model,
  messages:    ctx.prompt_messages,
  temperature: temperature,
  max_tokens:  max_tokens
});

return [{
  json: {
    ...ctx,
    gpt_request_body: gptBody,
    model_used:       model
  }
}];

const response = $input.first().json;
const ctx      = $('Build AI Prompt').first().json;

if (!response.choices || !response.choices[0]) {
  throw new Error('GPT returned no response: ' + JSON.stringify(response).slice(0, 300));
}

const raw_reply = response.choices[0].message.content;

// Extract intent tag
let ai_intent = 'general_inquiry';
const intentMatch = raw_reply.match(/Intent:\s*([a-zA-Z0-9_]+)/i);
if (intentMatch) {
  ai_intent = intentMatch[1].toLowerCase();
}

const ai_reply  = raw_reply.replace(/Intent:.*$/im, '').trim();

const prompt_tokens     = response.usage?.prompt_tokens    || 0;
const completion_tokens = response.usage?.completion_tokens || 0;
const latency_ms        = Date.now() - new Date(ctx.processed_at).getTime();

return [{
  json: {
    ...ctx,
    ai_reply,
    ai_intent,
    prompt_tokens,
    completion_tokens,
    latency_ms
  }
}];

// NODE 18: Prepare conversation upsert body
const ctx = $('Detect Intent & Create Record').first().json;

const convBody = JSON.stringify({
  tenant_id:                ctx.tenant_id,
  platform:                 ctx.platform,
  external_conversation_id: ctx.customer_phone,
  customer_name:            ctx.customer_name,
  customer_phone:           ctx.customer_phone,
  detected_language:        ctx.detected_language,
  status:                   'open',
  bot_enabled:              true,
  last_message_at:          new Date().toISOString(),
  last_message_preview:     (ctx.normalized_message || ctx.message || '').slice(0, 100),
  updated_at:               new Date().toISOString()
});

return [{ json: { ...ctx, conv_request_body: convBody } }];

// ─────────────────────────────────────────────
// NODE 20: Resolve conversation ID from upsert result
// ─────────────────────────────────────────────
const ctx          = $('Extract AI Reply').first().json;
const upsertResult = $input.first().json;

// Supabase returns array when Prefer: return=representation
const conv_id =
  (Array.isArray(upsertResult) && upsertResult[0]?.id)
    ? upsertResult[0].id
    : (upsertResult?.id || ctx.conversation_id || null);

return [{ json: { ...ctx, resolved_conversation_id: conv_id } }];

// NODE 21: Prepare customer + bot message insert bodies
const ctx = $input.first().json;
const conv_id = ctx.resolved_conversation_id;

const customerBody = JSON.stringify({
  conversation_id:     conv_id,
  sender_type:         'customer',
  content:              ctx.normalized_message || ctx.message,
  detected_language:   ctx.detected_language,
  external_message_id: ctx.external_message_id,
  is_read:             true
});

const botBody = JSON.stringify({
  conversation_id:     conv_id,
  sender_type:         'bot',
  content:             ctx.ai_reply,
  model_used:          ctx.model_used || null,
  prompt_tokens:       ctx.prompt_tokens || null,
  completion_tokens:   ctx.completion_tokens || null,
  latency_ms:          ctx.latency_ms || null,
  kb_chunks_used:      ctx.kb_count || 0,
  detected_language:   ctx.detected_language,
  external_message_id: ctx.external_message_id ? `${ctx.external_message_id}-reply` : null,
  is_read:             true
});

return [{ json: { ...ctx, customer_message_body: customerBody, bot_message_body: botBody } }];

// ─────────────────────────────────────────────
// NODE 23: Build final response JSON
// ─────────────────────────────────────────────
const ctx = $('Get Conversation ID').first().json;

return [{
  json: {
    ...ctx,
    success:         true,
    reply:           ctx.ai_reply,
    language:        ctx.detected_language,
    conversation_id: ctx.conversation_id || ctx.resolved_conversation_id,
    tenant_id:       ctx.tenant_id,
    model_used:      ctx.model_used,
    kb_chunks_used:  ctx.kb_count || 0,
    latency_ms:      ctx.latency_ms
  }
}];

// ─────────────────────────────────────────────
// NODE: Detect Intent & Create Record
// ─────────────────────────────────────────────
const ctx = $('Extract AI Reply').first().json;
const msg = ctx.message || ctx.normalized_message || '';
const msgLower = msg.toLowerCase();
const aiReply = ctx.ai_reply || '';

const intent = ctx.ai_intent || 'general_inquiry';

// Load the real previous order instead of {}
let previousInfo = {};
if (ctx.existing_order && typeof ctx.existing_order === 'object' && Object.keys(ctx.existing_order).length > 0) {
  previousInfo = ctx.existing_order;
} else {
  try {
    const rows = $('Load Existing Orders').first().json;
    const row = Array.isArray(rows) ? rows[0] : rows;
    if (row && Object.keys(row).length > 0) previousInfo = row;
  } catch (e) { /* no existing order, keep {} */ }
}

const previousOrderFinished = previousInfo.status && ['confirmed', 'cancelled', 'completed'].includes(previousInfo.status);

let createRecord = false;
let recordType = null;
let recordData = previousOrderFinished || Object.keys(previousInfo).length === 0
  ? {}
  : JSON.parse(JSON.stringify(previousInfo));

const niche = ctx.niche || 'general';

if (['ecommerce', 'restaurant', 'food_delivery'].includes(niche)) {
  const orderTriggerIntents = ['product_inquiry', 'order_placed', 'address_provided', 'order_confirmed', 'checkout_intent'];

  const hasActiveOrder = Object.keys(recordData).length > 0;
  const isOrderIntent = orderTriggerIntents.includes(intent);

  if (isOrderIntent || hasActiveOrder) {
    createRecord = true;
    recordType = 'order';

    let extractedItems = [];
    const cleanName = s => s.trim().replace(/\s+/g, ' ').replace(/^(i want|mujhe|muje|mjhe|chahiye|chahie|chaie|order|to order|buy|to buy|please|kindly|for|packs of|pack of|pieces of|piece of)\s+/gi, '').trim();

    // Prioritize AI's structured summary, support *Product(s)*: 
    const aiProductMatch = aiReply.match(/\*[Pp]roduct(?:s|\(s\))?\*\s*[:\-]\s*([^\n]+)/);
    const aiQtyMatch = aiReply.match(/\*[Qq]uantity\*\s*[:\-]\s*(\d+)/);

    // Parse totals robustly from bot or user message
    const combinedForPrice = aiReply + ' ' + msg;
    const unitPriceMatches = [...combinedForPrice.matchAll(/(?:USD|\\$|PKR|Rs\\.?|pkr)\s*([\d,.]+)\s*(?:per\s+pack|per\s+piece|each|\/pack|\/piece|\/pcs)|(?:price|costs)[\s\w]{0,15}(?:USD|\\$|PKR|Rs\\.?|pkr)\s*([\d,.]+)/gi)];
    let unitPrice = 0;
    if (unitPriceMatches.length > 0) {
       unitPrice = parseFloat((unitPriceMatches[0][1] || unitPriceMatches[0][2]).replace(/,/g, ''));
    }

    const totalMatches = [...aiReply.matchAll(/(?:total(?:\s+amount)?|amount|bill)[\s\w]*?(?:USD|\\$|PKR|Rs\\.?|pkr)\s*([\d,.]+)/gi)];
    let orderTotal = 0;
    if (totalMatches.length > 0) {
      orderTotal = parseFloat(totalMatches[totalMatches.length - 1][1].replace(/,/g, ''));
    }

    // Validate AI match
    const isAiValid = aiProductMatch && !/specify|which|unknown|missing|\?/i.test(aiProductMatch[1]);

    if (isAiValid) {
      let rawName = aiProductMatch[1];
      let parsedQty = 1;

      // Look for explicit price in product string, e.g., "6x Small bags @ PKR 400"
      const inlinePriceMatch = rawName.match(/@\s*(?:USD|\\$|PKR|Rs\\.?|pkr)\s*([\d,.]+)/i);
      if (inlinePriceMatch) {
        unitPrice = parseFloat(inlinePriceMatch[1].replace(/,/g, ''));
        rawName = rawName.replace(/@\s*(?:USD|\\$|PKR|Rs\\.?|pkr)\s*([\d,.]+)/i, '').trim();
      }

      // If AI outputs "4x Large paper bags", extract qty from the string itself
      const inlineQtyMatch = rawName.match(/^(\d+)[xX]\s*(.*)/);
      if (inlineQtyMatch) {
        parsedQty = parseInt(inlineQtyMatch[1]);
        rawName = inlineQtyMatch[2];
      } else if (aiQtyMatch) {
        parsedQty = parseInt(aiQtyMatch[1]);
      }

      extractedItems = [{ 
        name: cleanName(rawName).replace(/[.,]$/, ''),
        qty: parsedQty, 
        price: unitPrice 
      }];
    } else {
      // Fallback: Parse product name from Customer message manually
      const patA = /(\d+)\s*(?:pack|packs|piece|pieces|pcs|pc|item|items|x)\s+(?:of\s+)?([a-zA-Z0-9][a-zA-Z0-9\s\-\.\s]{2,50}?)(?=\s*(?:chaie|chahiye|chahie|order|deliver|pkr|rs|\.|,|$|\n))/gi;
      const patC = /(?:i\s+want(?:\s+to)?(?:\s+order)?|i\s+need(?:\s+to)?(?:\s+order)?|i\s+would\s+like|send\s+me|give\s+me|order)\s+([a-zA-Z0-9][a-zA-Z0-9\s\-\.\s]{1,50}?)\s+(\d+)\s*(?:pack|packs|piece|pieces|pcs|pc|item|items)/gi;
      const patD = /(?:mujhe|muje|mjhe|mjhay)\s+([a-zA-Z0-9][a-zA-Z0-9\s\-\.\s]{2,50}?)(?:\s+chaie|\s+chahiye|\s+chahie|\s+chahiyen|\s+lena|\s+order)/gi;
      const patE = /(?:product|item)\s*[:\-]?\s*([a-zA-Z0-9][a-zA-Z0-9\s\-\.\s]{2,50}?)\s+(\d+)\s*(?:pack|packs|piece|pieces|pcs)/gi;

      patE.lastIndex = 0;
      const matchesE = [...msg.matchAll(patE)];
      if (matchesE.length > 0) extractedItems = matchesE.map(m => ({ name: cleanName(m[1] || ''), qty: parseInt(m[2]) || 1, price: 0 }));

      if (extractedItems.length === 0) {
        patA.lastIndex = 0;
        const matchesA = [...msg.matchAll(patA)];
        if (matchesA.length > 0) extractedItems = matchesA.map(m => ({ name: cleanName(m[2] || ''), qty: parseInt(m[1]) || 1, price: 0 }));
      }

      if (extractedItems.length === 0) {
        patC.lastIndex = 0;
        const matchesC = [...msg.matchAll(patC)];
        if (matchesC.length > 0) extractedItems = matchesC.map(m => ({ name: cleanName(m[1] || ''), qty: parseInt(m[2]) || 1, price: 0 }));
      }

      if (extractedItems.length === 0) {
        patD.lastIndex = 0;
        const matchesD = [...msg.matchAll(patD)];
        if (matchesD.length > 0) extractedItems = matchesD.map(m => ({ name: cleanName(m[1] || ''), qty: 1, price: 0 }));
      }
    }

    const previousUnitPrice = (Array.isArray(previousInfo.items) && previousInfo.items[0] && previousInfo.items[0].price > 0)
      ? previousInfo.items[0].price
      : 0;

    if (extractedItems.length > 0) {
      if (unitPrice > 0) {
        extractedItems[0].price = unitPrice;
      } else if (orderTotal > 0 && extractedItems[0].qty > 0) {
        extractedItems[0].price = Math.round(orderTotal / extractedItems[0].qty);
      } else if (previousUnitPrice > 0) {
        extractedItems[0].price = previousUnitPrice;
      }
    }

    const previousOrderTotal = previousInfo.order_amount || 0;
    if (orderTotal === 0 && previousOrderTotal > 0) {
      orderTotal = previousOrderTotal;
    }

    let currentItems = [];
    if (extractedItems.length > 0) {
      currentItems = extractedItems;
    } else if (Array.isArray(previousInfo.items) && previousInfo.items.length > 0 && !previousInfo.items[0].name.includes('specify') && previousInfo.items[0].name !== 'Pending items' && previousInfo.items[0].name !== 'order') {
      currentItems = previousInfo.items;
    } else {
      currentItems = [{ name: 'Pending items', qty: 1, price: 0 }];
    }

    let deliveryAddress = recordData.delivery_address || null;
    const combinedForAddr = msg;
    const addrLabelMatch = combinedForAddr.match(/(?:[Dd]elivery\s+[Aa]ddress|[Dd]eliver\s+to|address(?: is)?|address to this)\s*[:\-]?\s*([^\n]{8,100})/i);

    let newAddress = null;
    if (addrLabelMatch) {
      newAddress = addrLabelMatch[1].replace(/[.!]+$/, '').trim();
    } else if (intent === 'address_provided' || !deliveryAddress) {
      const addrKeywords = /\b(dha|clifton|gulshan|phase|block|street|road|avenue|lane|sector|town|garden|colony|defence|bahria|nazimabad|korangi|malir|johar|askari|highway|rd\b)/i;
      const addrMatch = combinedForAddr.match(new RegExp(`[\\w\\s,\\.\\-\\/]{0,30}${addrKeywords.source}[^\\n\\.!]{0,40}`, 'i'));
      if (addrMatch) newAddress = addrMatch[0].trim();
    }

    if (newAddress) {
      deliveryAddress = newAddress;
    }


    let customerEmail = recordData.customer_email || null;
    const emailMatch = msg.match(/([a-zA-Z0-9._-]+@[a-zA-Z0-9._-]+\.[a-zA-Z0-9_-]+)/i);
    if (emailMatch) {
      customerEmail = emailMatch[1];
    } else if (!customerEmail) {
      const botEmailMatch = aiReply.match(/\*[Ee]mail\*\s*[:\-]\s*([a-zA-Z0-9._-]+@[a-zA-Z0-9._-]+\.[a-zA-Z0-9_-]+)/);
      if (botEmailMatch) customerEmail = botEmailMatch[1];
    }

    let paymentMethod = recordData.payment_method || null;
    if (!paymentMethod || intent === 'checkout_intent') {
      const combined = msgLower + ' ' + aiReply.toLowerCase();
      if (/\bcod\b|cash\s+on\s+delivery/.test(combined)) paymentMethod = 'COD';
      else if (/easypaisa/.test(combined)) paymentMethod = 'Easypaisa';
      else if (/jazzcash/.test(combined)) paymentMethod = 'JazzCash';
      else if (/bank\s*transfer/.test(combined)) paymentMethod = 'Bank Transfer';
    }

    // Only calculate total if we have valid items
    const calculatedTotal = orderTotal > 0 ? orderTotal : currentItems.reduce((s, i) => s + ((i.price || 0) * (i.qty || 1)), 0);

    const customerConfirmed = /^\s*(confirm(ed)?|order\s*karain|haan\s*confirm|yes,?\s*confirm|yes\s*proceed)\s*[.!]?\s*$/i.test(msg.trim());
    const aiConfirmed = /confirm ho gaya|order confirm|order placed|confirmed your order|order ki tayari|order accept|finalize your order|Your order is confirmed/i.test(aiReply);

    let newStatus = recordData.status || 'pending_address';
    if (intent === 'order_confirmed' || aiConfirmed || customerConfirmed) {
      newStatus = 'confirmed';
    } else if (deliveryAddress && paymentMethod && customerEmail) {
      newStatus = 'pending';
    } else if (deliveryAddress || customerEmail || intent === 'address_provided') {
      newStatus = 'pending';
    } else {
      newStatus = 'pending_address';
    }

    recordData = {
      ...recordData,
      tenant_id: ctx.tenant_id,
      conversation_id: ctx.conversation_id,
      customer_phone: ctx.customer_phone,
      customer_name: ctx.customer_name,
      customer_email: customerEmail,
      niche: niche,
      items: currentItems,
      order_amount: calculatedTotal,
      payment_method: paymentMethod,
      delivery_address: deliveryAddress,
      source: ctx.platform || 'whatsapp',
      handled_by: 'bot',
      status: newStatus,
      currency: 'USD',
    };

    if (intent === 'order_confirmed' || aiConfirmed || customerConfirmed) {
      recordData.confirmed_at = new Date().toISOString();
    }
  }
}

// ═══════════════════════════════════════════════════════════════
// DENTAL / SALON / CLINIC
// ═══════════════════════════════════════════════════════════════
if (['dental', 'salon', 'clinic'].includes(niche)) {
  if (['booking_intent', 'appointment_confirmed'].includes(intent)) {
    createRecord = true;
    recordType = 'appointment';

    const timeMatch = (msg + ' ' + aiReply).match(/(\d{1,2})(:\d{2})?\s*(am|pm|AM|PM)/);
    const dayMatch = (msg + ' ' + aiReply).match(/(monday|tuesday|wednesday|thursday|friday|saturday|sunday|tomorrow|kal|parso)/i);

    let apptDate = recordData.appointment_date || null;
    let apptTime = recordData.appointment_time || null;

    if (dayMatch && !apptDate) {
      const dayMap = { tomorrow:1,kal:1,parso:2,monday:0,tuesday:1,wednesday:2,thursday:3,friday:4,saturday:5,sunday:6 };
      const day = dayMatch[1].toLowerCase();
      const d2 = new Date();
      if (['tomorrow','kal','parso'].includes(day)) {
        d2.setDate(d2.getDate() + (dayMap[day] || 1));
      } else {
        const target = dayMap[day];
        const today = d2.getDay();
        const diff = (target - today + 7) % 7 || 7;
        d2.setDate(d2.getDate() + diff);
      }
      apptDate = d2.toISOString().split('T')[0];
    }

    if (timeMatch && !apptTime) {
      const hour = parseInt(timeMatch[1]);
      const isPM = timeMatch[3].toLowerCase() === 'pm';
      const hour24 = isPM && hour !== 12 ? hour + 12 : (!isPM && hour === 12 ? 0 : hour);
      apptTime = `${String(hour24).padStart(2,'0')}:00:00`;
    }

    recordData = {
      ...recordData,
      tenant_id: ctx.tenant_id,
      conversation_id: ctx.conversation_id,
      patient_name: ctx.customer_name,
      patient_phone: ctx.customer_phone,
      niche: niche,
      service_type: recordData.service_type || 'Consultation',
      appointment_date: apptDate,
      appointment_time: apptTime,
      status: intent === 'appointment_confirmed' ? 'confirmed' : 'pending',
      is_new_patient: ctx.is_new_conversation,
    };
  }
}

// ═══════════════════════════════════════════════════════════════
// REAL ESTATE
// ═══════════════════════════════════════════════════════════════
if (niche === 'realestate') {
  if (['property_inquiry','requirement_provided','visit_request'].includes(intent)) {
    createRecord = true;
    recordType = 'lead';

    const budgetMatch = msg.match(/(\d+\.?\d*)\s*(crore|lakh|cr|lac)/i);
    let budgetMax = recordData.budget_max || null;
    if (budgetMatch && !budgetMax) {
      const num = parseFloat(budgetMatch[1]);
      const unit = budgetMatch[2].toLowerCase();
      budgetMax = ['crore','cr'].includes(unit) ? num * 10000000 : num * 100000;
    }

    const bedMatch = msg.match(/(\d+)\s*(bed|bedroom|br)/i);
    let bedrooms = recordData.bedrooms || null;
    if (bedMatch && !bedrooms) bedrooms = parseInt(bedMatch[1]);

    recordData = {
      ...recordData,
      tenant_id: ctx.tenant_id,
      conversation_id: ctx.conversation_id,
      customer_name: ctx.customer_name,
      customer_phone: ctx.customer_phone,
      intent: recordData.intent || (msgLower.includes('rent') ? 'rent' : msgLower.includes('sell') ? 'sell' : 'buy'),
      bedrooms,
      budget_max: budgetMax,
      stage: intent === 'visit_request' ? 'visit_scheduled' :
             intent === 'requirement_provided' ? 'qualified' : (recordData.stage || 'new_inquiry'),
      temperature: 'warm',
      last_activity_at: new Date().toISOString(),
    };
  }
}

const needs_human_handoff = /human|agent|representative|insaan|baat|connect|transfer/i.test(msgLower);

return [{
  json: {
    ...ctx,
    detected_intent: intent,
    create_record: createRecord,
    record_type: recordType,
    record_data: recordData,
    needs_human_handoff: needs_human_handoff
  }
}];

